def max_path_sum(triangle, row, col):
    # Base case: if the triangle is empty, return 0
    if row == 0 and col == 0:
        return 0

    # If the current row and column are greater than the previous row and column,
    # then the maximum path sum is the current row and column
    if triangle[row - 1][col - 1] > triangle[row - 1][col - 1] + triangle[row - 1][col]:
        return max_path_sum(triangle, row - 1, col)

    # Otherwise, the maximum path sum is the current row and column + the maximum of the two
    # values in the current row and column
    else:
