def longest_common_subsequence(seq1, seq2, n, m):
    # Create a 2D list to store the longest common subsequences
    lcs = [[0 for x in range(m+1)] for y in range(n+1)]

    # Fill the lcs table
    for i in range(n+1):
        for j in range(m+1):
            if i == 0 or j == 0:
                lcs[i][j] = 0
            elif seq1[i-1] == seq2[j-1]:
                lcs[i][j] = lcs[i-1][j-1] + 1
            else:
                lcs[i][j] = max(lcs[i-1][j], lcs[i][j-1])

    # Find the longest common subsequence
    longest_subsequence = []
    i = n
    j = m
    while i > 0 and j > 0:
        if seq1[i-1] == seq2[j-1]:
